from typing import Sequence

def encode(book: Sequence[int], q: int) -> int:
    if q < 2 or any(d < 0 or d >= q for d in book):
        raise ValueError("invalid base or digit")
    value = 0
    for digit in book:
        value = q * value + digit
    return value

def decode(address: int, q: int, n: int) -> tuple[int, ...]:
    if q < 2 or n < 0 or not 0 <= address < q ** n:
        raise ValueError("invalid parameters")
    out = [0] * n
    for i in range(n - 1, -1, -1):
        address, out[i] = divmod(address, q)
    return tuple(out)

if __name__ == "__main__":
    b = (3, 1, 0, 2)
    a = encode(b, 4)
    print(b, a, decode(a, 4, 4))

from fractions import Fraction
from itertools import product
from typing import Callable

Book = tuple[int, ...]

def acceptance(q: int, n: int, checker: Callable[[Book], bool]) -> tuple[int, Fraction]:
    if q <= 0 or n < 0:
        raise ValueError("nonempty library required")
    count = sum(checker(tuple(w)) for w in product(range(q), repeat=n))
    return count, Fraction(count, q ** n)

if __name__ == "__main__":
    print(acceptance(2, 8, lambda w: sum(w) == 4))

from math import ceil

def place(total: int, books: int, capacity: int) -> list[tuple[int, int]]:
    if min(total, books, capacity) < 0 or total > books * capacity:
        raise ValueError("insufficient or invalid capacity")
    if total and capacity == 0:
        raise ValueError("zero capacity")
    return [divmod(i, capacity) for i in range(total)]

if __name__ == "__main__":
    total, capacity = 23, 5
    books = ceil(total / capacity)
    print(books, place(total, books, capacity))

